examples.template:
MonarchSectionCard(title = {{zone}}, tone = MonarchTone.Danger) {
    Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space1)) {
        transferredTo?.let { MonarchBanner(message = "$it is now the owner.", tone = MonarchTone.Success) }
        MonarchText(text = {{item.title}}, style = MonarchTextStyle.BodyStrong, heading = true)
        MonarchText(text = {{item.description}}, style = MonarchTextStyle.Caption, color = MonarchTheme.colors.textMuted)
        MonarchButton(
            text = {{item.action}},
            onClick = {
                step = 0
                newOwner = null
                open = true
            },
            variant = MonarchButtonVariant.Secondary,
        )
    }
}
if (open) {
    MonarchBottomSheet(onDismissRequest = { open = false }, title = "Transfer ownership") {
        Column(
            modifier = Modifier.verticalScroll(rememberScrollState()),
            verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space4),
        ) {
            MonarchStepper(steps = steps, current = step)
            when (step) {
                0 -> Column(verticalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space3)) {
                    MonarchText(
                        text = "The new owner gets full control of the workspace, including billing.",
                        color = MonarchTheme.colors.textMuted,
                    )
                    MonarchEntityPicker(
                        label = "New owner",
                        entities = members,
                        selected = newOwner,
                        onSelectedChange = { newOwner = it },
                        placeholder = "Choose a member",
                        helperText = "Choose a member to continue.",
                    )
                }
                1 -> MonarchConsequenceList(
                    items = listOf(
                        MonarchConsequence(MonarchConsequenceKind.Changed, "Your role changes to Admin"),
                        MonarchConsequence(
                            MonarchConsequenceKind.Removed,
                            "You can no longer delete the workspace or transfer ownership",
                        ),
                        MonarchConsequence(MonarchConsequenceKind.Changed, "$name becomes the owner"),
                        MonarchConsequence(
                            MonarchConsequenceKind.Warning,
                            "$name can change your role or remove you",
                        ),
                    ),
                    heading = "What changes",
                )
                else -> MonarchText(text = "Ownership moves to $name. Only the new owner can transfer it back.")
            }
            Row(
                modifier = Modifier.fillMaxWidth(),
                horizontalArrangement = Arrangement.spacedBy(MonarchTheme.spacing.space2, Alignment.End),
            ) {
                MonarchButton(
                    text = if (step == 0) "Cancel" else "Back",
                    onClick = { if (step == 0) open = false else step-- },
                    variant = MonarchButtonVariant.Secondary,
                )
                MonarchButton(
                    text = if (step == steps.lastIndex) "Transfer ownership" else "Continue",
                    onClick = {
                        if (step == steps.lastIndex) {
                            // Run the transfer through your API here, then close.
                            transferredTo = name
                            open = false
                        } else {
                            step++
                        }
                    },
                    variant = if (step == steps.lastIndex) {
                        MonarchButtonVariant.Danger
                    } else {
                        MonarchButtonVariant.Primary
                    },
                    enabled = newOwner != null,
                )
            }
        }
    }
}

examples.setupTemplate:
var open by rememberSaveable { mutableStateOf(true) }
var step by rememberSaveable { mutableIntStateOf(0) }
var newOwner by rememberSaveable { mutableStateOf<String?>(null) }
var transferredTo by rememberSaveable { mutableStateOf<String?>(null) }
val members = listOf(
    MonarchEntityPickerEntity({{candidates.0.id}}, {{candidates.0.name}}, description = {{candidates.0.email}}),
    MonarchEntityPickerEntity({{candidates.1.id}}, {{candidates.1.name}}, description = {{candidates.1.email}}),
    MonarchEntityPickerEntity({{candidates.2.id}}, {{candidates.2.name}}, description = {{candidates.2.email}}, hint = "Only admins can become the owner", enabled = false),
    MonarchEntityPickerEntity({{candidates.3.id}}, {{candidates.3.name}}, description = {{candidates.3.email}}, hint = {{candidates.3.ineligibleReason}}, enabled = false),
)
val steps = listOf(
    MonarchStepperStep("pick", "Choose the new owner"),
    MonarchStepperStep("review", "What changes"),
    MonarchStepperStep("confirm", "Confirm"),
)
val name = members.firstOrNull { it.id == newOwner }?.name.orEmpty()

